<?php /* Template Name: Reset Password */ $key = isset( $_GET['key'] ) ? sanitize_text_field( wp_unslash( $_GET['key'] ) ) : ''; $login = isset( $_GET['login'] ) ? sanitize_text_field( wp_unslash( $_GET['login'] ) ) : ''; get_header(); ?><main id="primary" class="sd-main sd-auth-main"><div class="sd-container sd-content-wrap"><div class="sd-auth-card"><div class="sd-auth-brand"><?php sd_render_site_branding(); ?></div><span class="sd-eyebrow"><?php esc_html_e( 'Choose a new password', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Set a new password', 'social-discovery' ); ?></h1><?php sd_auth_message(); ?><?php if ( function_exists( 'sd_core_reset_handler' ) && $key && $login ) : ?><form class="sd-form-grid" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="sd_reset_password"><input type="hidden" name="key" value="<?php echo esc_attr( $key ); ?>"><input type="hidden" name="login" value="<?php echo esc_attr( $login ); ?>"><?php wp_nonce_field( 'sd_reset_password' ); ?><div class="sd-field"><label for="sd-reset-pass1"><?php esc_html_e( 'New password', 'social-discovery' ); ?></label><div class="sd-password-field"><input id="sd-reset-pass1" name="pass1" type="password" minlength="8" autocomplete="new-password" required><button type="button" data-sd-toggle-password aria-label="<?php esc_attr_e( 'Show password', 'social-discovery' ); ?>">◉</button></div></div><div class="sd-field"><label for="sd-reset-pass2"><?php esc_html_e( 'Confirm new password', 'social-discovery' ); ?></label><input id="sd-reset-pass2" name="pass2" type="password" minlength="8" autocomplete="new-password" required></div><button class="sd-button sd-button-primary" type="submit"><?php esc_html_e( 'Update password', 'social-discovery' ); ?></button></form><?php else : ?><div class="sd-auth-message sd-auth-message-error" role="alert"><?php esc_html_e( 'This reset link is invalid or expired. Request a new one to continue.', 'social-discovery' ); ?></div><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_auth_url( 'forgot-password', wp_lostpassword_url() ) ); ?>"><?php esc_html_e( 'Request a new link', 'social-discovery' ); ?></a><?php endif; ?></div></div></main><?php get_footer(); ?>
